import {HEROES,STAT_LABELS,ARENAS,hero,newGame,bid,pass,canBid,botDecision,synergy,createBattle,battleStep} from './engine.mjs';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const icons={bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M14.5 8.5h-3a2 2 0 0 0 0 4h1a2 2 0 0 1 0 4h-3M12 6v12"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/>',cross:'<path d="m6 6 12 12M18 6 6 18"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 1 3-1 5-2 9-1v15c-4-1-6 0-9 1-3-1-5-2-9-1z"/>',sound:'<path d="M4 9v6h4l5 4V5L8 9zM17 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',play:'<path d="m8 5 12 7-12 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',check:'<path d="m5 12 4 4L19 6"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>'};
const icon=(name)=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.bolt}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let game;try{const saved=JSON.parse(localStorage.getItem('nexus-v1'));if(saved?.version===1&&saved.players?.length===2&&saved.pool?.length===10&&saved.pool.every(id=>hero(id))&&saved.players.every(p=>typeof p.name==='string'&&Number.isInteger(p.coins)&&p.coins>=0&&p.coins<=20&&p.team.every(id=>hero(id)))&&['auction','ready'].includes(saved.phase))game=saved;}catch{}
game??=newGame();let selectedBid=1,tab='auction',battle=null,playing=false,speed=1,sound=false,battleTimer,botTimer,viewFilter='Tümü',search='',compare=[],lastEvent=null;
const save=()=>{try{localStorage.setItem('nexus-v1',JSON.stringify(game));}catch{}};
const portrait=(h,cls='')=>`<div class="portrait ${cls}" role="img" aria-label="${esc(h.name)} çizgi roman portresi" style="--portrait:url('/assets/${h.id}.jpg');--hero-color:${h.color}"></div>`;
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3200);}
function beep(freq=400){if(!sound)return;try{const ctx=beep.ctx??=new AudioContext(),o=ctx.createOscillator(),gain=ctx.createGain();o.type='sine';o.frequency.value=freq;gain.gain.setValueAtTime(.045,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.17);o.connect(gain);gain.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.18);}catch{}}
function header(){return `<header class="header"><a href="#" class="brand" aria-label="Nexus ana sayfa" data-action="auction"><span class="brand-symbol">${icon('bolt')}</span>NEXUS<span class="brand-tag">ARENA</span></a><nav aria-label="Ana gezinme"><button class="nav-item ${tab==='auction'?'active':''}" data-action="auction">Açık artırma</button><button class="nav-item ${tab==='arena'?'active':''}" data-action="arena">Arena${game.phase==='auction'?'<span class="nav-lock">•</span>':''}</button><button class="nav-item ${tab==='library'?'active':''}" data-action="library">Karakter arşivi</button></nav><div class="header-actions"><button class="icon-button ${sound?'on':''}" data-action="sound" aria-label="Sesi ${sound?'kapat':'aç'}" title="Sesi ${sound?'kapat':'aç'}">${icon('sound')}</button><button class="outline small" data-action="rules">Nasıl oynanır? ${icon('book')}</button></div></header>`;}
function playerPanel(p,i){return `<section class="player-panel p${i}"><div class="player-top"><div class="player-avatar">${i===0?'01':'02'}</div><div><div class="eyebrow">${game.mode==='bot'&&i===1?'BOT RAKİP':'OYUNCU '+(i+1)}</div><h3>${esc(p.name)}</h3></div><div class="budget">${icon('coin')}<strong>${p.coins}</strong><span>coin</span></div></div><div class="roster-title"><span>Takımın</span><span>${p.team.length} / 5</span></div><div class="roster">${Array.from({length:5},(_,n)=>p.team[n]?`<button class="roster-hero" data-action="detail" data-id="${p.team[n]}" aria-label="${hero(p.team[n]).name}">${portrait(hero(p.team[n]))}<span>${hero(p.team[n]).name}</span></button>`:`<div class="empty-slot"><span>+</span></div>`).join('')}</div><div class="team-bonus">${icon('shield')}<span>${p.team.length?`Takım uyumu <b>+%${synergy(p.team)}</b>`:'İlk kahramanını bekliyor'}</span></div></section>`;}
function auction(){const h=hero(game.pool[Math.min(game.round,9)]),current=game.players[game.turn],min=game.bid+1;selectedBid=Math.max(min,Math.min(selectedBid,current.coins));const eligible=canBid(game,game.turn,selectedBid),botTurn=game.mode==='bot'&&game.turn===1;return `<main><section class="intro"><div><div class="eyebrow"><span class="tiny-square"></span> KAHRAMANLARIN BULUŞMA NOKTASI</div><h1>Takımını kur.<br>Arenaya <em>hükmet.</em></h1><p>20 coin. 10 kahraman. Tek kazanan.<br>Doğru teklif, bütün oyunu değiştirebilir.</p></div><div class="match-meta"><div class="session-tag"><span class="live-dot"></span>${game.mode==='bot'?'SEN + BOT':'2 OYUNCU · AYNI CİHAZ'}</div><button class="text-button" data-action="setup">${icon('refresh')} Yeni oyun</button><div class="phase-track"><span class="${game.phase==='auction'?'current':'completed'}"><b>01</b> Açık artırma</span><i></i><span class="${game.phase==='ready'?'current':''}"><b>02</b> Arena</span></div></div></section>${game.phase==='ready'?ready():`<div class="auction-layout"><section class="auction-stage"><div class="section-line"><h2><span class="live-dot"></span> AÇIK ARTIRMA</h2><span>LOT <b>${String(game.round+1).padStart(2,'0')}</b><span class="muted"> / 10</span></span></div><div class="hero-feature"><div class="feature-art">${portrait(h)}<div class="art-shade"></div><div class="art-top"><span class="rarity">${icon('star')} ${h.rating>=75?'EFSANEVİ':h.rating>=65?'DESTANSI':'KAHRAMAN'}</span><button class="glass-button" data-action="detail" data-id="${h.id}" aria-label="Karakter detayları">↗</button></div><div class="art-caption"><span>${h.group.toUpperCase()} / ${h.type.toUpperCase()}</span><h2>${h.name}</h2><p>${h.alias}</p></div><div class="art-number">${String(h.index+1).padStart(2,'0')}</div></div><div class="feature-info"><div class="feature-heading"><div class="eyebrow">KAHRAMAN PROFİLİ</div><div class="rating"><strong>${h.rating}</strong><span>GENEL<br>PUAN</span></div></div><p class="hero-quote">“${h.quote}”</p><div class="stats">${h.stats.map((v,i)=>`<div class="stat"><span>${STAT_LABELS[i]}</span><div class="stat-track"><i style="width:${v*10}%"></i></div><b>${v}<small>/10</small></b></div>`).join('')}</div><div class="skill"><span class="skill-icon">${icon('bolt')}</span><div><b>${h.skill}</b><p>${h.desc}</p></div></div><div class="bid-area"><div><span class="eyebrow">EN YÜKSEK TEKLİF</span><div class="current-bid">${icon('coin')}<strong>${game.bid||'—'}</strong><span>coin</span></div></div><div class="bid-owner">${game.leader===null?'İlk teklifi sen ver.':`${esc(game.players[game.leader].name)}<br><span>Şu an lider</span>`}</div></div></div></div><div class="bidding-console"><div class="whose-turn"><span class="turn-avatar p${game.turn}">${game.turn+1}</span><div><b>${botTurn?'Bot düşünüyor…':`${esc(current.name)}, sıra sende.`}</b><span>${current.team.length>=5?'Takımın dolu. Pas geçebilirsin.':current.coins<min?'Yeni teklif için yeterli coin yok.':'Teklifini yükselt veya karakteri rakibine bırak.'}</span></div></div><div class="bid-controls"><div class="stepper"><button data-action="minus" aria-label="Teklifi azalt" ${selectedBid<=min||botTurn?'disabled':''}>−</button><span>${selectedBid} ${icon('coin')}</span><button data-action="plus" aria-label="Teklifi artır" ${selectedBid>=current.coins||botTurn?'disabled':''}>+</button></div><button class="primary" data-action="bid" ${!eligible||botTurn?'disabled':''}>Teklif ver ${icon('arrow')}</button><button class="pass-button" data-action="pass" ${botTurn?'disabled':''}>Pas geç</button></div></div></section><aside class="players">${game.players.map(playerPanel).join('')}<div class="small-note">${icon('bolt')}<p><b>Birlikte daha güçlü.</b><br>Aynı gruptaki kahramanlar takım uyumunu artırır.</p></div></aside></div>`}<section class="pool-section"><div class="section-line"><h2>BU OYUNUN KAHRAMANLARI</h2><span class="muted">${Math.min(game.round,10)} / 10 tamamlandı</span></div><div class="pool">${game.pool.map((id,i)=>{const x=hero(id),lot=game.history.find(t=>t.id===id&&!t.reinforcement);return `<button class="pool-card ${i===game.round&&game.phase==='auction'?'current':''} ${i<game.round?'sold':''}" data-action="detail" data-id="${id}">${portrait(x)}<div class="pool-shade"></div><span class="pool-number">${String(i+1).padStart(2,'0')}</span>${lot?`<span class="owner-marker ${lot.winner===null?'unsold':'p'+lot.winner}">${lot.winner===null?'PAS':`P${lot.winner+1} · ${lot.price} ◈`}</span>`:i===game.round&&game.phase==='auction'?'<span class="current-marker">ŞİMDİ</span>':''}<strong>${x.name}</strong><span class="pool-type">${x.type}</span></button>`;}).join('')}</div></section></main>`;}
function ready(){return `<section class="ready-banner"><span class="ready-mark">${icon('check')}</span><div><div class="eyebrow">AÇIK ARTIRMA TAMAMLANDI</div><h2>Takımlar hazır. Söz arenada.</h2><p>${game.history.some(h=>h.reinforcement)?'Karakter alamayan takıma ücretsiz bir yedek kahraman verildi.':'Coinlerini kullandın. Şimdi stratejini konuştur.'}</p></div><button class="primary" data-action="arena">Arenaya geç ${icon('arrow')}</button></section><div class="ready-teams">${game.players.map(playerPanel).join('')}</div>`;}
function arenaView(){const a=ARENAS.find(a=>a.id===game.arena);return `<main><section class="intro arena-intro"><div><div class="eyebrow"><span class="tiny-square"></span> SON SÖZ ARENANIN</div><h1>İki takım.<br><em>Tek kazanan.</em></h1><p>${battle?'Her hamle, yeni bir olasılık.':'Savaş alanını seç. Şansı ayarla. Mücadeleyi başlat.'}</p></div><div class="match-meta"><span class="session-tag">${battle?`TUR ${String(battle.round).padStart(2,'0')}`:'TAKIMLAR HAZIR'}</span><button class="text-button" data-action="setup">${icon('refresh')} Yeni oyun</button></div></section>${!battle?`<div class="arena-config"><div><span class="eyebrow">SAVAŞ ALANI</span><div class="arena-options">${ARENAS.map(x=>`<button data-action="map" data-id="${x.id}" class="arena-option ${game.arena===x.id?'selected':''}"><span class="map-icon map-${x.id}">${icon(x.id==='city'?'bolt':x.id==='asgard'?'star':'shield')}</span><b>${x.name}</b><span>${x.desc}</span>${game.arena===x.id?icon('check'):''}</button>`).join('')}</div></div><div class="luck-setting"><label for="luck">Şans faktörü <strong id="luck-value">%${game.luck}</strong></label><input id="luck" type="range" min="0" max="25" value="${game.luck}"><p>Kritik vuruş olasılığı ve hasar sapması.<br>%0: sabit hasar; hızdan gelen kaçış devam eder.</p><button class="primary" data-action="start">Mücadeleyi başlat ${icon('play')}</button></div></div>`:''}<section class="battle-stage map-${a.id}"><div class="battle-topline"><span><span class="live-dot"></span> ${a.label}</span><span>${battle?battle.done?'MÜCADELE BİTTİ':playing?'CANLI MÜCADELE':'DURAKLATILDI':'MÜCADELEYE HAZIR'}</span></div><div class="city-skyline" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--height:${35+((i*31)%70)}%;--width:${26+(i%3)*18}px"></i>`).join('')}</div><div class="arena-teamheads"><div class="p0"><span>OYUNCU 01</span><h2>${esc(game.players[0].name)}</h2><p>Uyum +%${synergy(game.players[0].team)}</p></div><div class="vs">VS<span>${battle?'TUR '+battle.round:'NEXUS ARENA'}</span></div><div class="p1"><span>OYUNCU 02</span><h2>${esc(game.players[1].name)}</h2><p>Uyum +%${synergy(game.players[1].team)}</p></div></div><div class="fighters-grid">${[0,1].map(s=>`<div class="fighters side-${s}">${(battle?battle.fighters[s]:game.players[s].team.map(id=>({id,hp:1,maxHp:1,shield:0}))).map(f=>{const h=hero(f.id),attacking=lastEvent?.attacker===f.id&&lastEvent.side===s,hit=lastEvent?.target===f.id&&lastEvent.side!==s;return `<div class="fighter ${f.hp===0?'ko':''} ${attacking?'attacking':''} ${hit?'hit':''}">${portrait(h)}<span class="fighter-glow"></span>${hit?`<span class="floating-damage">${lastEvent.dodge?'KAÇIŞ':'−'+lastEvent.damage}</span>`:''}<div class="fighter-info"><b>${h.name}</b><div class="hp-track"><i style="width:${100*f.hp/f.maxHp}%"></i></div><span>${battle?`${Math.round(f.hp)} / ${f.maxHp} CAN`:'HAZIR'}${f.shield?' · '+f.shield+' KALKAN':''}</span></div>${f.hp===0?'<span class="ko-tag">ELENDİ</span>':''}</div>`;}).join('')}</div>`).join('')}</div>${battle?.done?`<div class="result-overlay"><div class="eyebrow">${battle.decision?'40 TUR · KALAN CAN ORANI':'MÜCADELE TAMAMLANDI'}</div><span class="winner-icon">${icon('star')}</span><h2>${battle.winner===null?'Berabere!':esc(game.players[battle.winner].name)+' kazandı!'}</h2><p>${battle.round} tur · ${battle.events.length} hamle · ${battle.events.filter(e=>e.crit).length} kritik vuruş</p><div><button class="primary" data-action="rematch">Aynı takımlarla rövanş ${icon('refresh')}</button><button class="glass-button" data-action="setup">Yeni oyun</button></div></div>`:''}</section>${battle?`<div class="battle-controls"><div><button class="outline" data-action="toggle-play" ${battle.done?'disabled':''}>${icon(playing?'pause':'play')}${playing?'Duraklat':'Devam et'}</button><button class="outline" data-action="step" ${playing||battle.done?'disabled':''}>Tek hamle ${icon('arrow')}</button></div><div class="speed-control"><span>Oynatma hızı</span>${[1,2,4].map(n=>`<button data-action="speed" data-id="${n}" class="${speed===n?'active':''}">${n}×</button>`).join('')}</div></div><section class="battle-log"><div class="section-line"><h2>MÜCADELE GÜNLÜĞÜ</h2><span class="muted">Son ${Math.min(battle.events.length,30)} hamle</span></div><div class="log-entries" aria-live="polite">${battle.events.slice(-30).reverse().map(e=>`<div class="log-entry"><span class="log-round">T${e.round}</span><span class="log-dot p${e.side}"></span><p><b>${hero(e.attacker).name}</b> → ${hero(e.target).name} <strong>${e.dodge?'KAÇIŞ':e.damage+' hasar'}</strong>${e.special?`<span class="log-badge">${e.skill}</span>`:''}${e.crit?'<span class="log-badge critical">KRİTİK</span>':''}${e.knockout?'<span class="log-badge">ELENDİ</span>':''}${e.extras.length?`<small>${e.extras.join(' · ')}</small>`:''}</p></div>`).join('')||'<p class="log-empty">İlk hamle bekleniyor…</p>'}</div></section>`:''}</main>`;}
function library(){const list=HEROES.filter(h=>(viewFilter==='Tümü'||h.type===viewFilter)&&(h.name+' '+h.alias).toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));return `<main><section class="intro"><div><div class="eyebrow"><span class="tiny-square"></span> GÜÇ, DOĞRU BİLGİYLE BAŞLAR</div><h1>Kahraman <em>arşivi.</em></h1><p>Özellikleri keşfet. Yetenekleri karşılaştır. Takımını düşün.</p></div><span class="session-tag">${HEROES.length} KARAKTER</span></section><div class="library-toolbar"><div class="filter-list">${['Tümü',...new Set(HEROES.map(h=>h.type))].map(t=>`<button data-action="filter" data-id="${t}" class="${viewFilter===t?'active':''}">${t}</button>`).join('')}</div><input type="search" id="search" placeholder="Kahraman ara…" aria-label="Kahraman ara" value="${esc(search)}"></div>${compare.length?`<div class="compare-bar"><span>${compare.map(id=>hero(id).name).join(' & ')} <small>(${compare.length}/2)</small></span><button class="primary small" data-action="compare" ${compare.length!==2?'disabled':''}>Karşılaştır ${icon('arrow')}</button><button class="text-button" data-action="clear-compare">Temizle</button></div>`:''}<div class="library-grid">${list.map(h=>`<article class="library-card"><button class="library-art" data-action="detail" data-id="${h.id}" aria-label="${h.name} detayları">${portrait(h)}<span class="library-rating">${h.rating}</span><div class="library-name"><span>${h.type.toUpperCase()}</span><h2>${h.name}</h2><p>${h.alias}</p></div></button><div class="library-card-footer"><span>${h.group}</span><button class="compare-check ${compare.includes(h.id)?'checked':''}" data-action="select-compare" data-id="${h.id}">${compare.includes(h.id)?icon('check'):'+'} Karşılaştır</button></div></article>`).join('')||'<p class="no-results">Bu aramada kahraman bulunamadı.</p>'}</div><p class="archive-note">Puanlar bu oyunun denge değerleridir. Resmî Marvel güç sıralaması değildir.</p></main>`;}
function render(){app.innerHTML=header()+(tab==='library'?library():tab==='arena'?arenaView():auction())+`<footer><a class="footer-brand" href="#" data-action="auction">NEXUS<span> / </span>ARENA</a><span>Strateji senin. Sonuç arenanın.</span><span>MARVEL EVRENİNDEN İLHAM ALAN FAN OYUNU</span></footer>`;scheduleBot();}
function showModal(content,cls=''){modal.className=cls;modal.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Kapat">${icon('cross')}</button>${content}`;if(!modal.open)modal.showModal();}
function detail(id){const h=hero(id);showModal(`<div class="detail-art">${portrait(h)}<div class="art-shade"></div><div class="art-caption"><span>${h.group.toUpperCase()}</span><h2>${h.name}</h2><p>${h.alias}</p></div></div><div class="detail-content"><div class="eyebrow">${h.type.toUpperCase()} · ${h.rating} GENEL PUAN</div><h2>${h.skill}</h2><p>${h.desc}</p><div class="stats">${h.stats.map((v,i)=>`<div class="stat"><span>${STAT_LABELS[i]}</span><div class="stat-track"><i style="width:${v*10}%"></i></div><b>${v}<small>/10</small></b></div>`).join('')}</div><div class="detail-tip">Özel yetenek her 3. saldırıda devreye girer. Aynı gruptan her ek kahraman +%4 takım uyumu sağlar (en fazla %12).</div></div>`,'detail-modal');}
function rules(){showModal(`<div class="modal-inner"><div class="eyebrow">NEXUS OYUN REHBERİ</div><h2>Tekliften zafere.</h2><div class="rule"><b>01</b><div><h3>20 coin ile başla.</h3><p>İki oyuncu aynı cihazdan sırayla oynar; istersen botu seç. 12 karakterden 10’u her oyunda rastgele gelir.</p></div></div><div class="rule"><b>02</b><div><h3>En iyi teklif kahramanı alır.</h3><p>Teklif en az 1 coin artar. Rakip pas geçince liderin teklifi ödenir. Teklif yokken iki pas karakteri atlar. Takım sınırı 5; coinsiz veya dolu takım pas geçer. Hiç karakter alamayan oyuncuya, sonunda satılmamış bir karakter ücretsiz verilir.</p></div></div><div class="rule"><b>03</b><div><h3>Güç, tek başına yetmez.</h3><p>Güç, enerji, teknoloji ve zekâ saldırıyı; dayanıklılık canı ve savunmayı; hız hamle sırasını ve kaçışı etkiler. Aynı gruptan ek karakter +%4 saldırı uyumu sağlar (en fazla %12).</p></div></div><div class="rule"><b>04</b><div><h3>Arenada izle.</h3><p>Özel yetenekler her 3. saldırıda çalışır. Şans ayarı kritik vuruş ihtimalini ve ±hasar sapmasını belirler; kritik hasar ×1,5. Hızdan gelen kaçış %2–16 arasında kalır. Arena bonusu %10. Son ayakta kalan takım kazanır; 40 turda sonuç yoksa kalan toplam can oranı karşılaştırılır.</p></div></div><button class="primary" data-action="close">Anladım, başlayalım ${icon('arrow')}</button></div>`);}
function setup(){showModal(`<form id="setup-form" class="modal-inner"><div class="eyebrow">YENİ BİR MÜCADELE</div><h2>Kimler arenaya çıkıyor?</h2><p>Her yeni oyunda kahramanlar yeniden karıştırılır.</p><div class="mode-options"><label><input type="radio" name="mode" value="local" ${game.mode==='local'?'checked':''}><span>Arkadaşınla oyna<small>Aynı cihazda 2 oyuncu</small></span></label><label><input type="radio" name="mode" value="bot" ${game.mode==='bot'?'checked':''}><span>Bota karşı oyna<small>Stratejini tek başına dene</small></span></label></div><label class="form-label">Oyuncu 1<input name="p1" maxlength="20" value="${esc(game.players[0].name)}" required></label><label class="form-label">Oyuncu 2<input name="p2" maxlength="20" value="${esc(game.players[1].name)}" required></label><button class="primary" type="submit">20 coin ile başla ${icon('arrow')}</button></form>`);modal.querySelectorAll('[name=mode]').forEach(el=>el.addEventListener('change',()=>{const bot=modal.querySelector('[name=mode]:checked').value==='bot';const p2=modal.querySelector('[name=p2]');p2.value=bot?'Nexus Bot':'Oyuncu 2';p2.readOnly=bot;}));}
function scheduleBot(){clearTimeout(botTimer);if(game.phase==='auction'&&game.mode==='bot'&&game.turn===1&&!modal.open){botTimer=setTimeout(()=>{const offer=botDecision(game);if(offer===null)pass(game);else bid(game,offer);selectedBid=game.bid+1;save();render();},950);}}
function step(){if(!battle||battle.done)return;lastEvent=battleStep(battle);if(lastEvent)beep(lastEvent.crit?750:300);if(battle.done){playing=false;clearTimeout(battleTimer);lastEvent=null;}render();}
function tick(){clearTimeout(battleTimer);if(playing&&!battle.done)battleTimer=setTimeout(()=>{step();tick();},1100/speed);}
function startBattle(){clearTimeout(battleTimer);battle=createBattle(game);lastEvent=null;playing=true;tab='arena';render();tick();}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const action=btn.dataset.action,id=btn.dataset.id;if(btn.tagName==='A')e.preventDefault();switch(action){case'auction':tab='auction';render();break;case'library':tab='library';render();break;case'arena':if(game.phase!=='ready'){toast('Önce açık artırmayı tamamla.');break;}tab='arena';render();break;case'sound':sound=!sound;beep(500);render();break;case'rules':rules();break;case'setup':setup();break;case'close':modal.close();scheduleBot();break;case'detail':detail(id);break;case'plus':selectedBid++;render();break;case'minus':selectedBid--;render();break;case'bid':if(bid(game,selectedBid)){beep(520);save();selectedBid=game.bid+1;render();}break;case'pass':pass(game);selectedBid=game.bid+1;save();render();break;case'map':game.arena=id;save();render();break;case'start':case'rematch':startBattle();break;case'toggle-play':playing=!playing;render();tick();break;case'step':step();break;case'speed':speed=Number(id);render();tick();break;case'filter':viewFilter=id;render();break;case'select-compare':if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<2)compare.push(id);else toast('Karşılaştırmak için en fazla 2 karakter seç.');render();break;case'clear-compare':compare=[];render();break;case'compare':if(compare.length===2){const hs=compare.map(hero);showModal(`<div class="modal-inner"><div class="eyebrow">KAHRAMAN KARŞILAŞTIRMASI</div><h2>Hangisi senin takımında?</h2><div class="compare-portraits">${hs.map(h=>`<div>${portrait(h)}<h3>${h.name}</h3><p>${h.group} · ${h.rating} puan</p></div>`).join('')}</div><table class="compare-table"><thead><tr><th>Özellik</th>${hs.map(h=>`<th>${h.name}</th>`).join('')}</tr></thead><tbody>${STAT_LABELS.map((s,i)=>`<tr><td>${s}</td>${hs.map(h=>`<td class="${h.stats[i]===Math.max(...hs.map(x=>x.stats[i]))?'best':''}">${h.stats[i]}/10</td>`).join('')}</tr>`).join('')}<tr><td>Yetenek</td>${hs.map(h=>`<td>${h.skill}</td>`).join('')}</tr></tbody></table></div>`,'compare-modal');}break;}});
document.addEventListener('input',e=>{if(e.target.id==='luck'){game.luck=Number(e.target.value);document.querySelector('#luck-value').textContent='%'+game.luck;save();}if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',e=>{if(e.target.id==='setup-form'){e.preventDefault();const data=new FormData(e.target);clearTimeout(botTimer);clearTimeout(battleTimer);playing=false;battle=null;lastEvent=null;game=newGame([data.get('p1'),data.get('mode')==='bot'?'Nexus Bot':data.get('p2')],data.get('mode'));selectedBid=1;tab='auction';modal.close();save();render();toast('Yeni oyun başladı. En iyi takım kazansın!');}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});modal.addEventListener('close',scheduleBot);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){playing=false;clearTimeout(battleTimer);render();}});
save();render();
